/* Local Instagram interactions. No action is sent to a real Instagram account. */
let simScreen=null,simCurrentPost=null,simStory=null,simStoryTimer=null;
let studioDrag=null,studioSuppressClick=0;
const simHeart=filled=>'<svg viewBox="0 0 24 24" width="24" height="24" fill="'+(filled?'currentColor':'none')+'" stroke="currentColor" stroke-width="1.8"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
const simCommentIcon=()=>svgLine('<path d="M21 11.5a9 9 0 1 1-4-7.5 9 9 0 0 1 4 7.5Z"/><path d="m18 18 3 3-1-6"/>');
function simButton(label,fn,icon){const b=dom('button','sim-button');b.type='button';b.setAttribute('aria-label',label);b.title=label;if(icon)b.innerHTML=icon;else b.textContent=label;b.addEventListener('click',fn);return b;}
function closeSimScreen(){clearTimeout(simStoryTimer);simStoryTimer=null;simStory=null;if(simScreen)simScreen.remove();simScreen=null;simCurrentPost=null;}
function createSimScreen(title,back=closeSimScreen){
 closeSimScreen();const phone=document.querySelector('.phone');simScreen=dom('section','sim-screen');simScreen.style.setProperty('--sim-nav-width',(phone.querySelector('.ig-desktop-nav').getBoundingClientRect().width||72)+'px');simScreen.setAttribute('aria-label',title);const head=dom('div','sim-topbar');head.append(simButton('Volver al perfil',back,igIcon('back')),dom('b','',title));const content=dom('div','sim-content');simScreen.append(head,content);phone.append(simScreen);return {screen:simScreen,head,content};
}
function showSimPost(index,comments=false){
 const tile=tiles[index],asset=lib.find(a=>a.id===tile?.imgId);if(!asset)return;
 const {screen,head,content}=createSimScreen('Publicaciones');simCurrentPost=index;screen.dataset.postIndex=index;
 const ids=tiles.map((t,i)=>t?i:-1).filter(i=>i>=0),position=ids.indexOf(index);
 const prev=simButton('Publicación anterior',()=>showSimPost(ids[position-1]),'‹'),next=simButton('Publicación siguiente',()=>showSimPost(ids[position+1]),'›');prev.disabled=position<=0;next.disabled=position>=ids.length-1;head.append(prev,next,simButton('Editar esta publicación',()=>editSimPost(index),'Editar'));
 const byline=dom('div','sim-byline'),av=dom('img');setSafeAvatar(av);av.alt='Foto del perfil';byline.append(av,dom('b','',profile.handle));if(tile.location)byline.append(dom('small','',tile.location));content.append(byline);
 const image=dom('img','sim-post-image');image.src=displaySrc(asset);image.alt=tile.caption||asset.name;image.addEventListener('dblclick',()=>{if(!tile.simLiked){tile.simLiked=true;save();showSimPost(index)}});content.append(image);
 const actions=dom('div','sim-post-actions');const like=simButton(tile.simLiked?'Quitar Me gusta':'Me gusta',()=>{tile.simLiked=!tile.simLiked;save();showSimPost(index)},simHeart(tile.simLiked));like.classList.toggle('liked',!!tile.simLiked);like.setAttribute('aria-pressed',String(!!tile.simLiked));actions.append(like,simButton('Ver comentarios',()=>showSimPost(index,true),simCommentIcon()));const bookmark=simButton(tile.simSaved?'Quitar de guardados':'Guardar publicación',()=>{tile.simSaved=!tile.simSaved;save();showSimPost(index)},svgLine('<path d="M6 3h12v18l-6-4-6 4Z"/>'));bookmark.classList.toggle('sim-bookmarked',!!tile.simSaved);bookmark.setAttribute('aria-pressed',String(!!tile.simSaved));actions.append(bookmark);content.append(actions);
 const count=simLikeCount(tile);const likes=simButton(count+' Me gusta',()=>showSimLikes(index));likes.classList.add('sim-like-count');content.append(likes);
 if(tile.caption){const cap=dom('p','sim-caption');cap.append(dom('b','',profile.handle+' '),document.createTextNode(tile.caption));content.append(cap)}
 const entries=Array.isArray(tile.commentEntries)?tile.commentEntries:[];
 const baseComments=Number(String(tile.comments||'0').replace(/[.,\s]/g,''));const commentCount=Number.isFinite(baseComments)?baseComments+entries.length:entries.length;
 const commentsButton=simButton('Ver comentarios ('+commentCount+')',()=>showSimPost(index,true));commentsButton.classList.add('sim-comments-link');content.append(commentsButton);
 if(tile.date)content.append(dom('small','sim-date',tile.date));
 const thread=dom('section','sim-comments');thread.id='simComments';thread.append(dom('h3','','Comentarios'));
 if(!entries.length)thread.append(dom('p','sim-empty-note','Todavía no hay comentarios en esta propuesta.'));
 entries.forEach(entry=>{const row=dom('div','sim-comment');row.append(dom('b','',entry.author||'vos'),dom('span','',entry.text));thread.append(row)});content.append(thread);
 const form=dom('form','sim-comment-form'),input=dom('input');input.placeholder='Agregá un comentario…';input.setAttribute('aria-label','Comentario');input.maxLength=2200;input.required=true;const send=dom('button','','Publicar');send.type='submit';form.append(input,send);form.addEventListener('submit',e=>{e.preventDefault();const text=input.value.trim();if(!text)return;if(!Array.isArray(tile.commentEntries))tile.commentEntries=[];tile.commentEntries.push({id:crypto.randomUUID(),author:'vos',text,createdAt:Date.now()});save();showSimPost(index,true)});content.append(form);
 if(comments)requestAnimationFrame(()=>{thread.scrollIntoView({block:'start'});input.focus({preventScroll:true})});
}
function editSimPost(index){const dialog=openPostEditor(index);if(dialog)dialog.addEventListener('close',()=>{if(simCurrentPost!==null)showSimPost(simCurrentPost)},{once:true});}
function editSimStories(id){clearTimeout(simStoryTimer);const position=simStory?.position||0;const dialog=openStoriesEditor(id);if(dialog)dialog.addEventListener('close',()=>{const h=profile.highlights.find(h=>h.id===id);if(h)showSimStory(id,Math.min(position,Math.max(0,storyItems(h).length-1)),true)},{once:true});}
function simLikeCount(tile){const raw=String(tile.likes||'0'),base=Number(raw.replace(/[.,\s]/g,''));return Number.isFinite(base)?String(base+(tile.simLiked?1:0)):raw+(tile.simLiked?' + vos':'');}
function showSimLikes(index){const tile=tiles[index];if(!tile)return;const {content}=createSimScreen('Me gusta',()=>showSimPost(index));content.append(dom('h3','sim-section-title',simLikeCount(tile)+' Me gusta'));if(tile.simLiked)content.append(dom('p','sim-list-row','♥ Vos'));const raw=String(tile.likes||'0');if(raw!=='0')content.append(dom('p','sim-empty-note',raw+' Me gusta definidos para esta propuesta.'));if(!tile.simLiked&&raw==='0')content.append(dom('p','sim-empty-note','Todavía no hay Me gusta.'));}
function storyItems(h){return h?.stories?.length?h.stories:h?.cover?[{src:normCover(h.cover).src}]:[];}
function showSimStory(id,position=0,paused=false){
 const h=profile.highlights.find(h=>h.id===id);if(!h)return;const stories=storyItems(h);const {screen,head,content}=createSimScreen(h.label);screen.classList.add('sim-story');simStory={id,position,paused};
 const pause=simButton(paused?'Reanudar historia':'Pausar historia',()=>showSimStory(id,position,!paused),paused?'▶':'Ⅱ');head.append(pause);
 const progress=dom('div','sim-story-progress');stories.forEach((_,i)=>{const segment=dom('span',i<position?'seen':i===position?'current':'');progress.append(segment)});content.append(progress);
 if(stories.length){const img=dom('img','sim-story-image');img.src=stories[position]?.src||stories[0].src;img.alt=h.label+' · historia '+(position+1);content.append(img)}else{content.append(dom('p','sim-empty-note','Este destacado todavía no tiene historias.'),simButton('Agregar historias',()=>editSimStories(id)))}
 const controls=dom('div','sim-story-controls');controls.append(simButton('Historia anterior',()=>advanceSimStory(-1),'‹'),dom('span','',stories.length?(position+1)+' / '+stories.length:h.label),simButton('Historia siguiente',()=>advanceSimStory(1),'›'));content.append(controls);
 const edit=simButton('Editar historias',()=>editSimStories(id));edit.classList.add('sim-story-edit');content.append(edit);
 let sx=null;content.addEventListener('touchstart',e=>{sx=e.touches[0]?.clientX},{passive:true});content.addEventListener('touchend',e=>{if(sx===null)return;const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>40)advanceSimStory(dx<0?1:-1);sx=null},{passive:true});
 if(stories.length&&!paused&&!document.hidden)simStoryTimer=setTimeout(()=>advanceSimStory(1),6000);
}
function advanceSimStory(delta){if(!simStory)return;const {id,position,paused}=simStory,h=profile.highlights.find(h=>h.id===id),n=storyItems(h).length,next=position+delta;if(next>=0&&next<n){showSimStory(id,next,paused);return}const hi=profile.highlights.findIndex(h=>h.id===id),target=profile.highlights[hi+delta];if(target)showSimStory(target.id,delta<0?Math.max(0,storyItems(target).length-1):0,paused);else closeSimScreen();}
function simNavigate(name){
 if(name==='Perfil'||name==='Instagram'){closeSimScreen();currentProfileTab='posts';render();applyProfile();return}
 if(name==='Inicio'){const first=tiles.findIndex(Boolean);if(first>=0)showSimPost(first);else closeSimScreen();return}
 if(name==='Reels'){closeSimScreen();currentProfileTab='reels';render();applyProfile();return}
 if(name==='Nueva publicación'){fileInput.click();return}
 if(name==='Buscar'){showSimSearch();return}
 if(name==='Mensajes'){showSimMessages();return}
 if(name==='Notificaciones'){showSimNotifications();return}
 switchWorkspace('profile');
}
function showSimSearch(){const {content}=createSimScreen('Buscar');const input=dom('input','sim-search');input.placeholder='Buscar publicaciones';input.setAttribute('aria-label','Buscar publicaciones');const results=dom('div','sim-search-results');const redraw=()=>{results.replaceChildren();const query=input.value.trim().toLowerCase();tiles.forEach((tile,i)=>{if(!tile)return;const a=lib.find(a=>a.id===tile.imgId);if(!a||query&&![tile.caption,tile.location,a.name].some(t=>String(t||'').toLowerCase().includes(query)))return;const b=simButton('Abrir resultado '+(i+1),()=>showSimPost(i)),img=dom('img');img.src=displaySrc(a);img.alt=tile.caption||a.name;b.append(img);results.append(b)});if(!results.children.length)results.append(dom('p','sim-empty-note','No hay publicaciones que coincidan.'))};input.addEventListener('input',redraw);content.append(input,results);redraw();}
function showSimMessages(){const {content}=createSimScreen('Mensajes');content.append(dom('p','sim-empty-note','Conversación de prueba de esta propuesta.'));const list=dom('div','sim-message-list');(profile.simMessages||[]).forEach(m=>list.append(dom('p','sim-message',m.text)));content.append(list);const form=dom('form','sim-comment-form'),input=dom('input');input.placeholder='Escribí un mensaje…';input.setAttribute('aria-label','Mensaje');input.maxLength=2200;input.required=true;const send=dom('button','','Enviar');send.type='submit';form.append(input,send);form.addEventListener('submit',e=>{e.preventDefault();const text=input.value.trim();if(!text)return;if(!Array.isArray(profile.simMessages))profile.simMessages=[];profile.simMessages.push({id:crypto.randomUUID(),text,createdAt:Date.now()});saveProfile();showSimMessages()});content.append(form);}
function showSimNotifications(){const {content}=createSimScreen('Notificaciones');let count=0;tiles.forEach((t,i)=>{if(!t)return;if(t.simLiked){content.append(simButton('Te gustó la publicación '+(i+1),()=>showSimPost(i)));count++}if(t.commentEntries?.length){content.append(simButton(t.commentEntries.length+' comentarios en la publicación '+(i+1),()=>showSimPost(i,true)));count++}});if(!count)content.append(dom('p','sim-empty-note','Las interacciones de esta propuesta aparecerán acá.'));}
function initSimulator(){
 const phone=document.querySelector('.phone');phone.querySelector('.ig-follow').addEventListener('click',()=>{profile.simFollowing=!profile.simFollowing;applyProfile();saveProfile()});phone.querySelector('.ig-message').addEventListener('click',showSimMessages);
 document.addEventListener('keydown',e=>{if(!simScreen||e.target.closest('input,textarea,[contenteditable=true]'))return;if(e.key==='Escape'){e.preventDefault();closeSimScreen()}else if(simStory&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();advanceSimStory(e.key==='ArrowRight'?1:-1)}});
 document.addEventListener('visibilitychange',()=>{if(simStory){const s={...simStory};showSimStory(s.id,s.position,document.hidden||s.paused)}});
}
function finishStudioDrop(target){if(!studioDrag)return;const fromLibrary=studioDrag.kind==='tray';if(target>=0&&target<total){closeSimScreen();if(studioDrag.kind==='cell'){const src=studioDrag.src;if(src!==target){[tiles[src],tiles[target]]=[tiles[target],tiles[src]];normalizeBanners();sel.clear();render();updateExportUI();commit()}}else placeAsset(target,studioDrag.imgId)}if(fromLibrary&&target>=0&&typeof closeWorkspace==='function')closeWorkspace();if(typeof document!=='undefined')document.body.classList.remove('placing-photo');studioDrag=null;studioSuppressClick=Date.now()+350;clearDrop();ghost.style.display='none';}
function wireStudioDrag(el,data){
 el.draggable=false;
 let mouseStart=null,mouseMoving=false;
 el.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,input,.del'))return;e.preventDefault();mouseStart={x:e.clientX,y:e.clientY};mouseMoving=false;el.setPointerCapture(e.pointerId)});
 el.addEventListener('pointermove',e=>{if(!mouseStart||e.pointerType!=='mouse')return;if(!mouseMoving&&Math.hypot(e.clientX-mouseStart.x,e.clientY-mouseStart.y)>6){mouseMoving=true;studioDrag={...data};if(data.kind==='tray')document.body.classList.add('placing-photo');const asset=lib.find(a=>a.id===(data.imgId||tiles[data.src]?.imgId));if(asset)showGhost(displaySrc(asset));el.classList.add('dragging')}if(mouseMoving){e.preventDefault();moveGhost(e.clientX,e.clientY);hintDrop(cellAt(e.clientX,e.clientY));const main=document.querySelector('.ig-main'),r=main.getBoundingClientRect();if(e.clientY<r.top+40)main.scrollTop-=15;else if(e.clientY>r.bottom-40)main.scrollTop+=15}});
 const finishMouse=e=>{if(!mouseStart)return;if(mouseMoving)finishStudioDrop(e.type==='pointercancel'?-1:cellAt(e.clientX,e.clientY));mouseStart=null;mouseMoving=false;el.classList.remove('dragging')};el.addEventListener('pointerup',finishMouse);el.addEventListener('pointercancel',finishMouse);
 let timer=null,start=null,held=false,scrolling=false,lastTouchY=0;let scrollHost=null;
 const cancel=()=>{clearTimeout(timer);timer=null;held=false;scrolling=false;start=null;document.body.classList.remove('placing-photo');el.classList.remove('dragging');clearDrop();ghost.style.display='none';studioDrag=null};
 el.addEventListener('touchstart',e=>{if(e.target.closest('button,input')||e.touches.length!==1)return;const t=e.touches[0];scrollHost=el.closest('.ig-main,.sidebar');start={x:t.clientX,y:t.clientY};lastTouchY=t.clientY;scrolling=false;timer=setTimeout(()=>{held=true;studioDrag={...data};if(data.kind==='tray')document.body.classList.add('placing-photo');const asset=lib.find(a=>a.id===(data.imgId||tiles[data.src]?.imgId));if(asset)showGhost(displaySrc(asset));moveGhost(start.x,start.y);el.classList.add('dragging');if(navigator.vibrate)navigator.vibrate(20)},320)},{passive:true});
 el.addEventListener('touchmove',e=>{if(!start)return;const t=e.touches[0];if(!held){if(Math.hypot(t.clientX-start.x,t.clientY-start.y)>8){clearTimeout(timer);scrolling=true}if(scrolling&&scrollHost){e.preventDefault();scrollHost.scrollTop+=lastTouchY-t.clientY}lastTouchY=t.clientY;return}e.preventDefault();moveGhost(t.clientX,t.clientY);hintDrop(cellAt(t.clientX,t.clientY));const main=document.querySelector('.ig-main'),r=main.getBoundingClientRect();if(t.clientY<r.top+45)main.scrollTop-=15;else if(t.clientY>r.bottom-45)main.scrollTop+=15},{passive:false});
 el.addEventListener('touchend',e=>{clearTimeout(timer);if(scrolling){e.preventDefault();studioSuppressClick=Date.now()+350}if(held){e.preventDefault();const t=e.changedTouches[0];finishStudioDrop(cellAt(t.clientX,t.clientY))}cancel()},{passive:false});el.addEventListener('touchcancel',cancel,{passive:true});
}
